#!/usr/bin/env python3
# AI DISCLAIMER: All of the text in this file was generated by AI.
"""Print the prune tip-scan table from runs.csv: per run, then T/N as the ratio of the medians, with "no overlap"
when the two arms' ranges are disjoint. Also recomputes each run's pass figures from passes/<run>.csv and its
windows 1-6 rate and CPU per block from windows/<run>.csv, and checks them against runs.csv.
usage: python3 scripts/score.py <data dir>"""
import csv, os, statistics, sys
d = sys.argv[1]
rows = list(csv.DictReader(open(os.path.join(d, "runs.csv"))))
bad = 0
for r in rows:
    ms = [int(p["ms"]) for p in csv.DictReader(open(os.path.join(d, "passes", r["run"] + ".csv")))]
    b = w = c = 0.0
    for x in csv.DictReader(open(os.path.join(d, "windows", r["run"] + ".csv"))):
        if 1 <= int(x["window"]) <= 6:
            b += float(x["blocks"]); w += float(x["wall_s"]); c += float(x["blocks"]) * float(x["cpu_s_per_block"])
    p90 = sorted(ms)[min(len(ms) - 1, int(round(0.9 * (len(ms) - 1))))]
    again = (len(ms), statistics.median(ms), p90, sum(ms), "%.3f" % (b / w), "%.4f" % (c / b))
    given = (int(r["passes"]), float(r["median_pass_ms"]), int(r["p90_pass_ms"]), int(r["sum_pass_ms"]), r["w1_6_blocks_per_s"], r["w1_6_cpu_s_per_block"])
    if again != given:
        bad += 1; print("MISMATCH", r["run"], again, given)
print("%-6s %6s %8s %8s %9s %8s %9s %7s %10s %5s %9s" % ("run", "passes", "med_ms", "p90_ms", "sum_s", "blk/s", "cpu_s/blk", "top_s", "hash", "ERROR", "tipcheck"))
for r in rows:
    print("%-6s %6s %8s %8s %9.1f %8s %9s %7s %10s %5s %9s" % (r["run"], r["passes"], r["median_pass_ms"], r["p90_pass_ms"], int(r["sum_pass_ms"]) / 1000,
          r["w1_6_blocks_per_s"], r["w1_6_cpu_s_per_block"], r["launch_to_top_s"], r["hash_check"], r["error_lines"], r["tipcheck"]))
for k, lab in (("median_pass_ms", "median pass"), ("p90_pass_ms", "90th-percentile pass"), ("sum_pass_ms", "summed pruning time"),
               ("w1_6_blocks_per_s", "sync rate, windows 1-6"), ("w1_6_cpu_s_per_block", "CPU per block, windows 1-6"), ("launch_to_top_s", "launch to top")):
    t = [float(r[k]) for r in rows if r["arm"] == "T"]; n = [float(r[k]) for r in rows if r["arm"] == "N"]
    ratio = statistics.median(t) / statistics.median(n)
    print("T/N %-28s %.3f (%+.1f%%), %s" % (lab, ratio, 100 * (ratio - 1), "no overlap" if max(t) < min(n) or max(n) < min(t) else "overlap"))
print("every run: stop height reached, HASH_OK, 0 ERROR lines, TIPCHECK ok: %s" % ("yes" if all(r["hash_check"] == "HASH_OK" and r["error_lines"] == "0" and r["tipcheck"] == "ok" for r in rows) else "NO"))
print("recomputed from passes/ and windows/: %s" % ("all match" if not bad else "%d MISMATCH" % bad))
